(()=>{'use strict';const {$,$$,euro:M,num:N,escape:E}=RFL;const engines=RFL.engines={};
function feedback(el,heading,text,good=true){el.innerHTML=`<div class="feedback ${good?'good':'retry'}" role="status"><h3>${heading}</h3><p>${text}</p></div>`}
function scenario(root,id){const data=window.RFL_SCENARIOS[id];let index=0,score=0,answers=[];function draw(){if(index===data.length){RFL.complete(id);root.innerHTML=`<div class="scenario"><span class="eyebrow">Activity complete</span><h2>${id==='risk'?'There isn’t one right attitude to risk.':'Good decisions start with better questions.'}</h2>${id==='risk'?`<p>You chose the certain option ${answers.filter((a,i)=>a===0).length} times out of ${data.length}. This describes these fictional choices, not your personality or suitability for any investment.</p>`:`<div class="result-score">${score} / ${data.length}</div><p>First-attempt answers. Read the takeaways below and try the activity again whenever you like.</p>`}<div class="result-card"><h3>Take these ideas with you</h3><ul>${[...new Set(data.map(x=>x.lesson))].map(x=>`<li>${x}</li>`).join('')}</ul></div><p class="small">Recorded in My learning. Completion is a practice record, not certification.</p><button class="button" id="play-again">Try again</button></div>`;$('#play-again',root).onclick=()=>{index=0;score=0;answers=[];draw()};return}const s=data[index];root.innerHTML=`<div class="scenario"><div class="game-progress"><span>${index+1} of ${data.length}</span><progress value="${index}" max="${data.length}" aria-label="Scenario progress"></progress><span>${id==='risk'?'Reflection':score+' correct'}</span></div><span class="eyebrow">${id==='influencer'?'A fictional social feed':id==='provenance'?'Evidence beats appearances':'A fictional situation'}</span><h2>${s.title}</h2><div class="scenario-context">${E(s.context)}</div><div class="options">${s.options.map((o,i)=>`<button class="option" data-choice="${i}">${E(o)}</button>`).join('')}</div><div id="scenario-feedback" aria-live="polite"></div></div>`;$$('[data-choice]',root).forEach(b=>b.onclick=()=>{const c=+b.dataset.choice,good=s.correct===null||c===s.correct;answers.push(c);if(c===s.correct)score++;$$('[data-choice]',root).forEach(x=>{x.disabled=true;if(+x.dataset.choice===s.correct)x.classList.add('correct')});b.classList.add(s.correct===null?'chosen':good?'correct':'incorrect');$('#scenario-feedback',root).innerHTML=`<div class="feedback ${good?'good':'retry'}"><h3>${s.correct===null?'A choice worth thinking about':good?'That’s a sound choice.':'Here’s a safer way to think about it.'}</h3><p>${E(s.explanation)}</p><p><strong>Remember:</strong> ${E(s.lesson)}</p></div><div class="button-row"><button class="button" id="next-scenario">${index===data.length-1?'See my takeaways':'Next situation'}</button></div>`;$('#next-scenario',root).onclick=()=>{index++;draw();root.scrollIntoView({block:'start',behavior:'instant'})}})}draw()}
['scam','privacy','influencer','adviser','provenance','risk','hallucination'].forEach(id=>engines[id]=root=>scenario(root,id));
engines.inflation=root=>{root.innerHTML=`<div class="lab-columns"><div class="controls">${RFL.range('infl-amount','Money today',100,10000,100,1000,'euro')}${RFL.range('infl-rate','Annual inflation',0,15,.5,3,'percent')}${RFL.range('infl-years','Years into the future',1,30,1,10)}<p class="small muted">Hold the money fixed. Change only the price level. The rate is an assumption, not a forecast.</p></div><div><div id="infl-stats" class="stat-grid"></div><div class="chart-wrap"><div class="chart-title"><strong>What happens to €1,000?</strong></div><div id="infl-chart"></div></div><div id="infl-note"></div><div id="infl-table"></div></div></div><div id="infl-check"></div>`;function calc(){const p=+$('#infl-amount').value,r=+$('#infl-rate').value/100,y=+$('#infl-years').value,factor=(1+r)**y;$('#infl-stats').innerHTML=RFL.stat('Unchanged amount',M(p))+RFL.stat('Buying power',M(p/factor))+RFL.stat('Same basket costs',M(p*factor));$('.chart-title strong',root).textContent=`What happens to ${M(p)}?`;const rows=Array.from({length:y+1},(_,i)=>({x:i,y:p/(1+r)**i,z:p*(1+r)**i}));$('#infl-chart').innerHTML=RFL.lineChart(rows,['Buying power in today’s euros','Cost of the same basket']);$('#infl-note').innerHTML=`<div class="note">After ${y} years, your ${M(p)} still says ${M(p)} on the account. It buys about <strong>${N(100/factor,1)}%</strong> of what it buys today. To buy the original basket, you would need ${M(p*factor,2)}.</div>`;$('#infl-table').innerHTML=RFL.dataTable(rows,['Year','Buying power','Same basket price'],['x','y','z'],[null,v=>M(v,2),v=>M(v,2)])}RFL.bindRanges(root,calc);calc();RFL.check($('#infl-check'),'inflation','If prices rise by 10%, what is the purchasing power of a fixed €100 in today’s euros?',['€90 exactly','About €90.91','€110'],1,'Divide €100 by 1.10. The future basket price rises, while a fixed sum buys less.');};
engines.compound=root=>{let mode='saving';root.innerHTML=`<div class="lab-columns"><div class="controls"><div class="segmented" aria-label="Calculation mode"><button data-mode="saving" aria-pressed="true">Saving</button><button data-mode="borrowing" aria-pressed="false">Borrowing</button></div>${RFL.range('ci-start','Starting amount',0,20000,100,1000,'euro')}${RFL.range('ci-month','Monthly saving',0,1000,10,100,'euro')}${RFL.range('ci-rate','Nominal annual rate',0,30,.5,5,'percent')}${RFL.range('ci-years','Years',1,40,1,10)}<p class="small muted">Fixed nominal annual rate ÷ 12. Interest is added monthly; deposits or payments follow at month-end. No taxes or fees.</p></div><div><div class="stat-grid" id="ci-stats"></div><div class="chart-wrap"><div class="chart-title"><strong id="ci-title">Give your savings time</strong></div><div id="ci-chart"></div></div><div id="ci-note"></div><div id="ci-table"></div></div></div><div id="ci-check"></div>`;function calc(){const p=+$('#ci-start').value,c=+$('#ci-month').value,r=+$('#ci-rate').value,y=+$('#ci-years').value;const d=mode==='saving'?RFL.savings(p,c,r,y):RFL.debt(p,c,r,y);$('#ci-stats').innerHTML=mode==='saving'?RFL.stat('Final balance',M(d.balance))+RFL.stat('Money paid in',M(d.paid))+RFL.stat('Interest added',M(d.interest)):RFL.stat('Debt remaining',M(d.balance))+RFL.stat('Total repaid',M(d.paid))+RFL.stat('Interest charged',M(d.interest));$('#ci-chart').innerHTML=RFL.lineChart(d.rows,mode==='saving'?['Savings balance','Money paid in']:['Debt remaining','Total repaid']);$('#ci-title').textContent=mode==='saving'?'Give your savings time':'Follow what you still owe';$('#ci-note').innerHTML=`<div class="note">${mode==='saving'?`You contribute ${M(d.paid,2)}. At this fixed illustrative rate, interest adds ${M(d.interest,2)}. Returns on real investments are uncertain.`:d.payoff?`This debt is paid off in ${d.payoff} months under these assumptions. Once the balance reaches zero, no further payments are made.`:c<p*r/1200?`Your payment is less than the first month’s interest (${M(p*r/1200,2)}). The unpaid interest increases the balance: this is negative amortisation.`:Math.abs(c-p*r/1200)<1e-8&&p>0?`Your payment covers only the monthly interest. The balance never decreases under these fixed assumptions.`:d.balance>0?`After ${y} years, ${M(d.balance,2)} remains. A smaller payment can stretch repayment over a much longer period.`:'There is no outstanding debt.'}</div>`;$('#ci-table').innerHTML=RFL.dataTable(d.rows,['Year',mode==='saving'?'Savings':'Debt',mode==='saving'?'Paid in':'Repaid'],['x','y','z'],[null,v=>M(v,2),v=>M(v,2)])}$$('[data-mode]',root).forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]',root).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('label[for=ci-month]').textContent=mode==='saving'?'Monthly saving':'Monthly repayment';$('#ci-rate').value=mode==='saving'?5:12;$('#ci-rate-out').textContent=$('#ci-rate').value+'%';calc()});RFL.bindRanges(root,calc);calc();RFL.check($('#ci-check'),'compound','You owe €1,000 at a nominal annual rate of 12%, compounded monthly. Your first payment is €5. What happens?',['The debt falls by €5','The debt stays unchanged','The debt rises to €1,005'],2,'The first month adds €10 in interest, then subtracts the €5 payment.');};
engines.loan=root=>{root.innerHTML=`<div class="lab-columns"><div class="controls">${RFL.range('loan-amount','Amount borrowed',500,30000,500,5000,'euro')}${RFL.range('loan-rate','Nominal annual rate',0,25,.5,8,'percent')}${RFL.range('loan-years','Repayment term in years',1,10,1,3)}<p class="small muted">Fixed monthly payments, no fees, no missed payments. This nominal rate is not an all-in APR. A real offer may include additional costs.</p></div><div><div class="stat-grid" id="loan-stats"></div><div class="chart-wrap"><div class="chart-title"><strong>Remaining balance</strong></div><div id="loan-chart"></div></div><div id="loan-split"></div><div id="loan-table"></div></div></div><div id="loan-check"></div>`;function calc(){const p=+$('#loan-amount').value,r=+$('#loan-rate').value,n=+$('#loan-years').value*12,d=RFL.loan(p,r,n);$('#loan-stats').innerHTML=RFL.stat('Each month',M(d.payment,2))+RFL.stat('Interest cost',M(d.totalInterest,2))+RFL.stat('Total repaid',M(d.total,2));const yearly=[{x:0,y:p},...d.rows.filter(x=>x.month%12===0).map(x=>({x:x.month/12,y:x.balance}))];$('#loan-chart').innerHTML=RFL.lineChart(yearly,['Debt remaining'],false);$('#loan-split').innerHTML=`<div class="note"><strong>First payment:</strong> ${M(d.rows[0].interest,2)} interest + ${M(d.rows[0].principal,2)} principal.<br><strong>Last payment:</strong> ${M(d.rows.at(-1).interest,2)} interest + ${M(d.rows.at(-1).principal,2)} principal.<br>${r>0?'As the balance falls, less of each payment goes to interest.':'At 0% interest, every payment goes entirely to principal.'}</div>`;$('#loan-table').innerHTML=RFL.dataTable(d.rows,['Month','Payment','Interest','Principal','Remaining'],['month','payment','interest','principal','balance'],[null,...Array(4).fill(v=>M(v,2))])}RFL.bindRanges(root,calc);calc();RFL.check($('#loan-check'),'loan','For the same positive interest rate and loan amount, a longer repayment term usually means…',['A lower monthly payment but more total interest','A higher payment and less total interest','No change in the total interest'],0,'You owe money for longer. Compare the monthly payment and the overall cost.');};
engines.diversification=root=>{const assets=['Cash','Bonds','Broad shares','Tech shares'];const scenarios=[{name:'Recession',returns:[0,2,-20,-35],why:'Cash holds its nominal value, while the fictional shares fall. Bonds rise in this particular scenario, not in every recession.'},{name:'Inflation shock',returns:[0,-12,-8,-15],why:'Several assets lose value together. Cash has no nominal loss here, but inflation still reduces what it buys.'},{name:'Technology boom',returns:[0,1,12,35],why:'Concentration can look attractive when its chosen sector rises. One favourable scenario says little about the next one.'},{name:'Rates rise',returns:[0,-10,-9,-18],why:'Bond prices can fall when market rates rise. The simplified scenario also has falling shares.'}];let active=0;root.innerHTML=`<div class="lab-columns"><div><h3>Split a fictional €10,000</h3><p class="small muted">Set relative weights. They are normalised to 100% so the whole amount is allocated.</p><div class="weights">${assets.map((a,i)=>`<div class="weight-row"><label for="asset-${i}">${a}</label><input type="range" min="0" max="100" value="25" id="asset-${i}"><output id="weight-${i}">25%</output></div>`).join('')}</div><div class="note">These are invented stress tests, not real assets, historical results or forecasts. No allocation is recommended.</div></div><div><div class="filter-row">${scenarios.map((s,i)=>`<button class="filter-button" data-shock="${i}" aria-pressed="${i===0}">${s.name}</button>`).join('')}</div><div class="stat-grid" id="div-stats"></div><div id="div-result" aria-live="polite"></div><div class="table-scroll"><table><thead><tr><th>Asset</th><th>Allocation</th><th>Scenario move</th><th>Gain / loss</th></tr></thead><tbody id="div-table"></tbody></table></div></div></div><div id="div-check"></div>`;function calc(){const raw=assets.map((_,i)=>+$('#asset-'+i).value),sum=raw.reduce((a,b)=>a+b,0);if(!sum){$('#div-result').innerHTML='<div class="feedback retry">Give at least one asset a positive weight.</div>';$('#div-stats').innerHTML='';$('#div-table').innerHTML='';raw.forEach((_,i)=>$('#weight-'+i).textContent='0%');return}const weights=raw.map(x=>x/sum),s=scenarios[active],ret=weights.reduce((acc,w,i)=>acc+w*s.returns[i],0);weights.forEach((w,i)=>$('#weight-'+i).textContent=N(w*100,1)+'%');$('#div-stats').innerHTML=RFL.stat('Starting value',M(10000))+RFL.stat('After the shock',M(10000*(1+ret/100)))+RFL.stat('Scenario change',N(ret,2)+'%');$('#div-result').innerHTML=`<div class="note">${s.why} Diversification spreads exposure; it cannot guarantee a profit or prevent every loss.</div>`;$('#div-table').innerHTML=assets.map((a,i)=>`<tr><td>${a}</td><td>${M(weights[i]*10000,2)}</td><td>${s.returns[i]}%</td><td>${M(weights[i]*10000*s.returns[i]/100,2)}</td></tr>`).join('')}$$('input',root).forEach(el=>el.oninput=calc);$$('[data-shock]',root).forEach(b=>b.onclick=()=>{active=+b.dataset.shock;$$('[data-shock]',root).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));calc()});calc();RFL.check($('#div-check'),'diversification','What can you conclude if your mix loses money in the inflation shock?',['Diversification never helps','Several assets can fall together even in a diversified mix','The next shock must produce a gain'],1,'Spreading exposure reduces dependence on one asset. It does not make all risks disappear.');};
engines.prompt=root=>{const parts=[['context','Give relevant context','Use a fictional student with €1,500 monthly take-home income and €1,050 essential costs.'],['task','Ask for a specific task','Compare two ways to reserve €150 a month, using a small table and plain language.'],['boundaries','Set useful boundaries','Do not recommend financial products. Do not request personal or account information.'],['check','Ask for verification','Show the arithmetic, state assumptions and identify what I should check independently.']];root.innerHTML=`<div class="lab-columns"><div><h3>Make the request clearer</h3><p>Start with “Help me with money.” Add instructions and compare what changes.</p>${parts.map(([id,t,d])=>`<label class="check-label"><input type="checkbox" data-prompt="${id}"><span><strong>${t}</strong><br><span class="small">${d}</span></span></label>`).join('')}<p class="small muted">This workshop assembles scripted examples. It does not contact an AI service or judge a live model.</p></div><div><h3>Your prompt</h3><div class="prompt-preview" id="prompt-text"></div><h3 style="margin-top:24px">Worked example response</h3><div id="prompt-response" class="task-box"></div><div class="note">A careful prompt can improve a request. It cannot guarantee a correct answer. You still need to check the result.</div></div></div><div id="prompt-check"></div>`;function calc(){const selected=parts.filter(([id])=>$(`[data-prompt=${id}]`).checked),ids=selected.map(x=>x[0]);$('#prompt-text').textContent=['Help me with money.',...selected.map(x=>x[2])].join('\n\n');$('#prompt-response').innerHTML=ids.includes('context')?`<p>For this fictional example, €1,500 − €1,050 leaves €450 before flexible spending and saving.</p>${ids.includes('task')?'<p><strong>Plan A:</strong> set aside €150 at the start of the month and limit flexible spending to €300.<br><strong>Plan B:</strong> reserve €75 twice a month, with the same €300 flexible-spending limit.</p><p>Both reserve €150. Different timing may suit different pay schedules.</p>':'<p>A useful next step would be to say whether you want a monthly budget, a saving plan or an explanation of borrowing costs.</p>'}${ids.includes('boundaries')?'<p>These are planning examples, with no product recommendations or private details needed.</p>':''}${ids.includes('check')?'<p><strong>Check:</strong> €1,050 + €300 + €150 = €1,500. The calculation assumes reliable monthly income and excludes irregular bills. Check those before using the plan.</p>':''}`:'<p>“Money” could mean budgeting, saving, debt or understanding a price. Without a specific task and fictional context, a response has little to work with.</p>';if(ids.length===4)$('#prompt-response').innerHTML+='<p><strong>You now have a specific, bounded request and a checkable response.</strong></p>'}$$('[data-prompt]',root).forEach(x=>x.onchange=calc);calc();RFL.check($('#prompt-check'),'prompt','Which instruction adds a useful verification step?',['Be absolutely certain and never disagree','Show the arithmetic and tell me what needs checking','Write like a famous financial expert'],1,'Ask for evidence and assumptions, then inspect them yourself. Confident style is not a check.');};
engines['tiny-ai']=root=>{const train=[{amount:35,days:28,label:0},{amount:80,days:25,label:0},{amount:150,days:20,label:0},{amount:220,days:29,label:0},{amount:700,days:1,label:1},{amount:850,days:2,label:1},{amount:600,days:3,label:1},{amount:450,days:1,label:1}];const test=[{amount:50,days:24,label:0},{amount:780,days:2,label:1},{amount:900,days:27,label:0},{amount:90,days:1,label:1}];let trained=false;root.innerHTML=`<p>In this invented dataset, the classroom answer key labels some transactions “review”. A label is not proof of fraud. The model sees only amount and days since the recipient was added.</p><div class="lab-columns"><div><h3>1. Choose the training labels</h3><p class="small muted">Try changing a few labels. “Review” means investigate, not automatically block.</p>${train.map((x,i)=>`<div class="train-row"><label for="train-${i}">${M(x.amount)} · recipient ${x.days} days old</label><select id="train-${i}"><option value="0" ${x.label===0?'selected':''}>Ordinary</option><option value="1" ${x.label===1?'selected':''}>Review</option></select></div>`).join('')}<div class="button-row"><button class="button" id="train-model">Train & test</button><button class="button secondary" id="reset-labels">Reset labels</button></div></div><div><h3>2. Inspect the result</h3><div id="model-result" aria-live="polite"><div class="empty">Train the model to see its predictions on four examples it has not learned from.</div></div><div class="note"><strong>The actual rule:</strong> divide amount by 1,000 and days by 30, then compute the average feature pair for each class. Predict the class with the nearest average, using squared Euclidean distance. Scaling and labels affect the result.</div><p class="small muted">This is a local nearest-centroid classifier, not a language model or a usable fraud detector. Four test cases cannot establish real-world accuracy.</p></div></div><div id="tiny-check"></div>`;function run(){const labels=train.map((_,i)=>+$('#train-'+i).value),centers=[0,1].map(k=>{const rows=train.filter((x,i)=>labels[i]===k);return rows.length?{x:rows.reduce((s,x)=>s+x.amount/1000,0)/rows.length,y:rows.reduce((s,x)=>s+x.days/30,0)/rows.length}:null});if(centers.some(x=>!x)){feedback($('#model-result'),'Both classes need examples','Give at least one training example to each class before fitting this two-class model.',false);return}const pred=test.map(t=>{const dist=centers.map(c=>(t.amount/1000-c.x)**2+(t.days/30-c.y)**2);return dist[1]<dist[0]?1:0}),correct=pred.filter((x,i)=>x===test[i].label).length;trained=true;$('#model-result').innerHTML=`<div class="stat-grid">${RFL.stat('Classroom test',correct+' / 4')}${RFL.stat('False alarms',pred.filter((x,i)=>x===1&&test[i].label===0).length)}${RFL.stat('Missed reviews',pred.filter((x,i)=>x===0&&test[i].label===1).length)}</div><div class="table-scroll"><table><thead><tr><th>Unseen example</th><th>Prediction</th><th>Answer key</th></tr></thead><tbody>${test.map((t,i)=>`<tr><td>${M(t.amount)} / ${t.days} days</td><td>${pred[i]?'Review':'Ordinary'}</td><td>${t.label?'Review':'Ordinary'} ${pred[i]===t.label?'✓':'≠'}</td></tr>`).join('')}</tbody></table></div><p>Compare the large payment to an established recipient and the small payment to a new recipient. Two numbers cannot tell the full story.</p><svg class="dot-chart" viewBox="0 0 360 200" role="img" aria-label="Training examples and learned class averages. Horizontal axis: amount, zero to one thousand euros. Vertical axis: recipient age, zero to thirty days."><path d="M40 15v155h300" stroke="#899ab0" fill="none"/><text x="40" y="190" font-size="12">€0</text><text x="285" y="190" font-size="12">€1,000</text>${train.map((t,i)=>`<circle cx="${40+t.amount/1000*285}" cy="${170-t.days/30*150}" r="6" fill="${labels[i]?'#a36100':'#2855d9'}"/>`).join('')}${centers.map((c,i)=>`<rect x="${34+c.x*285}" y="${164-c.y*150}" width="12" height="12" fill="none" stroke="${i?'#a36100':'#2855d9'}" stroke-width="3"/>`).join('')}</svg><p class="small">Blue: ordinary. Amber: review. Squares: learned class averages.</p>`}$('#train-model').onclick=run;$$('select',root).forEach(x=>x.onchange=()=>{if(trained)$('#model-result').innerHTML='<div class="note">Labels changed. Choose “Train & test” to fit the model again.</div>'});$('#reset-labels').onclick=()=>{train.forEach((t,i)=>$('#train-'+i).value=t.label);run()};RFL.check($('#tiny-check'),'tiny-ai','Why might a model trained on poor labels make poor decisions?',['It learns patterns from those labels, even when they are misleading','A model automatically fixes every labelling mistake','Test accuracy on four examples proves it is safe'],0,'Labels, features and evaluation all matter. A small demonstration is not evidence of real-world reliability.');};
engines.budget=root=>{const items=[{name:'Rent',amount:600,min:600,cat:'needs'},{name:'Food',amount:220,min:180,cat:'needs'},{name:'Transport',amount:90,min:60,cat:'needs'},{name:'Utilities',amount:100,min:100,cat:'needs'},{name:'Subscriptions',amount:45,min:0,cat:'wants'},{name:'Leisure',amount:110,min:0,cat:'wants'},{name:'Emergency saving',amount:150,min:0,cat:'reserve'}];let income=1500,shock=0,assigned=Array(7).fill('');root.innerHTML=`<p>Alex takes home €1,500 a month. Sort each item by its main role, then adjust the amounts. Drag a card onto a category or use its select menu.</p><div class="stat-grid" id="budget-stats"></div><div class="drop-grid">${[['needs','Essentials'],['wants','Flexible spending'],['reserve','Future buffer']].map(([id,t])=>`<div class="drop-zone" data-zone="${id}"><h3>${t}</h3><p class="small" id="zone-${id}">No items yet</p></div>`).join('')}</div><div class="budget-items">${items.map((x,i)=>`<div class="budget-item" draggable="true" data-item="${i}"><div><label for="budget-amount-${i}" class="item-name"><span class="drag-handle" draggable="true" aria-hidden="true" title="Drag this item">⠿</span> ${x.name} (€)</label><input id="budget-amount-${i}" type="number" min="${x.min}" max="3000" step="5" value="${x.amount}" style="width:105px" aria-describedby="budget-rules"></div><select aria-label="Category for ${x.name}" data-category="${i}"><option value="">Choose category</option><option value="needs">Essentials</option><option value="wants">Flexible spending</option><option value="reserve">Future buffer</option></select></div>`).join('')}</div><p id="budget-rules" class="small muted">For this fictional household, rent and utilities are fixed; food needs at least €180 and transport €60. Needs vary with context. Here, the subscriptions are optional entertainment services.</p><div class="task-box"><h3>Now change the month</h3><label for="budget-shock">Choose a surprise</label><select id="budget-shock"><option value="0">No surprise</option><option value="income">Income falls by €200</option><option value="rent">Rent rises by 15% (€90)</option><option value="laptop">Essential repair costs €300</option></select><p class="small" style="margin-top:12px">Goal: cover the stated essentials, put at least €50 into a buffer, and keep spending within the available income.</p><button class="button" id="budget-check">Check my plan</button></div><div id="budget-feedback" aria-live="polite"></div>`;function calc(){income=$('#budget-shock').value==='income'?1300:1500;shock=$('#budget-shock').value==='rent'?90:$('#budget-shock').value==='laptop'?300:0;const vals=items.map((_,i)=>+$('#budget-amount-'+i).value||0),sum=vals.reduce((a,b)=>a+b,0)+shock;$('#budget-stats').innerHTML=RFL.stat('Income',M(income))+RFL.stat('Planned + surprise',M(sum))+RFL.stat('Left to assign',M(income-sum));['needs','wants','reserve'].forEach(c=>{$('#zone-'+c).textContent=items.filter((_,i)=>assigned[i]===c).map(x=>x.name).join(', ')||'No items yet'})}$$('[data-category]',root).forEach(x=>x.onchange=()=>{assigned[+x.dataset.category]=x.value;calc()});$$('input',root).forEach(x=>x.oninput=calc);$('#budget-shock').onchange=calc;$$('[data-item]',root).forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.item));$$('[data-zone]',root).forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('over')};z.ondragleave=()=>z.classList.remove('over');z.ondrop=e=>{e.preventDefault();z.classList.remove('over');const i=Number(e.dataTransfer.getData('text/plain'));if(Number.isInteger(i)&&i>=0&&i<items.length){assigned[i]=z.dataset.zone;$(`[data-category="${i}"]`).value=z.dataset.zone;calc()}}});$('#budget-check').onclick=()=>{const vals=items.map((_,i)=>+$('#budget-amount-'+i).value),correct=items.every((x,i)=>assigned[i]===x.cat),valid=vals.every((v,i)=>Number.isFinite(v)&&v>=items[i].min&&v<=3000),total=vals.reduce((a,b)=>a+b,0)+shock;if(!correct)return feedback($('#budget-feedback'),'Check the categories','In this scenario rent, food, transport and utilities are essentials; entertainment subscriptions and leisure are flexible; emergency saving builds the buffer.',false);if(!valid)return feedback($('#budget-feedback'),'Keep the essentials covered','At least one amount falls below the stated minimum or is not a valid amount. A workable plan cannot simply erase the household’s essential costs.',false);if(total>income)return feedback($('#budget-feedback'),'There’s still a gap',`The plan is ${M(total-income)} over income. Adjust flexible spending or saving while keeping the essentials and at least €50 for a buffer.`,false);if(vals[6]<50)return feedback($('#budget-feedback'),'Leave room for a buffer','For this exercise, keep at least €50 in emergency saving. Try reducing an optional cost.',false);RFL.complete('budget');feedback($('#budget-feedback'),'The plan fits',`You have covered the given essentials and set aside ${M(vals[6])}. There is ${M(income-total)} left unassigned. ${shock||income<1500?'You also adapted the plan to a surprise.':'Try a surprise next and see what changes.'} Recorded in My learning.`)};calc();};
engines.detective=root=>{const rows=[['Rent',600,false,'The agreed rent is a known essential cost.'],['Grocery shop',48.20,false,'An ordinary purchase in this fictional statement.'],['Streambox',9.99,true,'This appears twice on the same date. Check the invoice and whether there are two accounts before assuming fraud.'],['Streambox',9.99,true,'This second same-day subscription charge needs checking.'],['Cash withdrawal fee',3.50,true,'A disclosed fee may be legitimate, but it is a recurring cost worth comparing.'],['Mystery Media',29,true,'The account holder does not recognise this merchant. Check receipts and contact the bank through its official app or known number if still unfamiliar.'],['Bus pass',45,false,'A known transport expense.'],['Music plan — unused for 3 months',7.99,true,'The charge may be authorised, but an unused subscription is a candidate for cancellation.']];root.innerHTML=`<div class="lab-columns"><div><h3>Statement: 4–10 May</h3><p>Jamie recognises the rent, groceries and bus pass. Select every entry that deserves a closer look. An item can be worth checking without being fraud.</p>${rows.map((r,i)=>`<label class="check-label"><input type="checkbox" value="${i}"><span>${r[0]}<br><strong>${M(r[1],2)}</strong></span></label>`).join('')}<button class="button" id="detective-check">Compare my findings</button></div><div><div class="receipt"><h3>What Jamie knows</h3><p>One streaming account.<br>No second account for a flatmate.<br>Music app no longer used.<br>“Mystery Media” is unfamiliar.</p><div class="receipt-row"><span>Statement total</span><strong>${M(rows.reduce((s,x)=>s+x[1],0),2)}</strong></div></div><div id="detective-feedback" aria-live="polite"></div></div></div>`;$('#detective-check').onclick=()=>{const selected=$$('input:checked',root).map(x=>+x.value),right=rows.every((x,i)=>selected.includes(i)===x[2]);$('#detective-feedback').innerHTML=`<div class="feedback ${right?'good':'retry'}"><h3>${right?'You found the items to investigate.':'Compare your choices with the clues.'}</h3><ul>${rows.filter(x=>x[2]).map(x=>`<li><strong>${x[0]}:</strong> ${x[3]}</li>`).join('')}</ul><p>Potential duplicate streaming (€9.99) plus unused music (€7.99) would be €215.76 over a year if both repeated monthly. This is a reason to investigate, not a confirmed saving or fraud finding.</p></div>`;if(right){RFL.complete('detective');$('#detective-feedback').innerHTML+='<p class="small">Recorded in My learning.</p>'}}};
engines.subscriptions=root=>{const plans=[['Video',8.99],['Music',6.99],['Fitness app',4.99],['Cloud space',2.99],['Gaming pass',9.99],['Premium delivery',5.99]];root.innerHTML=`<div class="lab-columns"><div><h3>Which subscriptions do you keep?</h3><p>Pick a fictional bundle. Watch the annual cost, then try keeping only the services you would use.</p>${plans.map((p,i)=>`<label class="check-label"><input type="checkbox" data-sub="${i}" checked><span>${p[0]} <strong>${M(p[1],2)} / month</strong></span></label>`).join('')}</div><div><div class="stat-grid" id="sub-stats"></div><div class="receipt" id="sub-receipt"></div><div class="note">An annual plan is not automatically better value. Check whether you need the service, the cancellation terms, and what happens after any introductory price ends.</div></div></div><div id="sub-check"></div>`;function calc(){const chosen=$$('[data-sub]:checked',root).map(x=>plans[+x.dataset.sub]),total=chosen.reduce((a,b)=>a+b[1],0);$('#sub-stats').innerHTML=RFL.stat('Every month',M(total,2))+RFL.stat('Over one year',M(total*12,2))+RFL.stat('Over three years',M(total*36,2));$('#sub-receipt').innerHTML='<h3>The annual view</h3>'+chosen.map(p=>`<div class="receipt-row"><span>${p[0]}</span><strong>${M(p[1]*12,2)}</strong></div>`).join('')+`<div class="receipt-row"><span>Total</span><strong>${M(total*12,2)}</strong></div><p class="small">Constant prices; no discounts or additional fees.</p>`}$$('input',root).forEach(x=>x.onchange=calc);calc();RFL.check($('#sub-check'),'subscriptions','A service costs €4.99 a month after its trial. What is twelve months at that price?',['€49.90','€59.88','€64.99'],1,'€4.99 × 12 = €59.88. Check renewal dates before a free trial becomes a paid plan.');};
engines.life=root=>{const events=[
{title:'A place to begin',text:'Your new room needs a few essentials. How will you organise them?',options:[{label:'Buy a new starter set · €120',cost:120,why:'Convenient, but it uses cash that could support the first unexpected bill.'},{label:'Choose second-hand essentials · €45',cost:45,why:'A lower upfront cost keeps more cash available. Check condition and safety.'},{label:'Borrow what you can for now · €0',cost:0,why:'Borrowing items can give you time. This assumes someone has suitable items to lend.'}]},
{title:'The laptop stops working',text:'You need a working computer for study. Three workable options are available in this fictional month.',options:[{label:'Repair it · €140',cost:140,why:'Repair is less costly than replacement here. In real life, check the diagnosis and quote.'},{label:'Buy a refurbished replacement · €300',cost:300,why:'Replacement solves the immediate need but takes a larger bite from your buffer.'},{label:'Use a loan device; pay a setup fee · €25',cost:25,why:'Shared access can bridge a difficult month. It is useful only if it meets your actual needs.'}]},
{title:'A little extra work',text:'A known local organisation offers paid weekend tasks. All amounts below are net of the fictional task costs.',options:[{label:'Take two shifts · earn €140',income:140,why:'Extra income creates room in the plan. Whether you have time and energy matters too.'},{label:'Take one shift · earn €70',income:70,why:'A smaller commitment still adds flexibility.'},{label:'Keep the weekend free · earn €0',income:0,why:'A budget has to fit your life as well as your balance. Review what you can afford this month.'}]},
{title:'“Pay the parcel fee now”',text:'A message says a parcel is waiting and requests €2 to release it. You have not checked the sender.',options:[{label:'Check through the courier’s known website · €0',cost:0,why:'A separate, trusted channel lets you verify without using the message link.'},{label:'Ignore the link and contact the seller · €0',cost:0,why:'The seller can help establish whether there really is a parcel.'},{label:'Use the message link · simulated loss €180',cost:180,why:'In this fictional scenario the page is fraudulent. Contact the bank promptly through a trusted route after suspected compromise. The simulated loss is illustrative.'}]},
{title:'A higher housing bill',text:'An unexpected one-off housing adjustment is due. The provider offers two written arrangements.',options:[{label:'Pay the full adjustment · €100',cost:100,why:'Paying now settles this fictional bill, but reduces available cash.'},{label:'Use the provider’s agreed reduction · €60',cost:60,why:'Checking available support can change a difficult bill. This option is specific to the scenario.'},{label:'Pay late under the stated terms · €120',cost:120,why:'Here, delaying adds a €20 fee. Read the terms before assuming a delay is costless.'}]},
{title:'A smaller payslip',text:'This month’s income is €300 lower. How do you respond?',incomeChange:-300,options:[{label:'Cover the shortfall from available funds · €0 extra',cost:0,why:'A buffer exists for uneven months. Notice whether the shortfall forces borrowing.'},{label:'Take an extra shift · earn €80',income:80,why:'Extra work softens, but does not fully remove, the income drop.'},{label:'Sell an unused item safely · receive €60',income:60,why:'A one-off sale can help this month, and it is not a reliable replacement for income.'}]},
{title:'The subscription renewal',text:'An optional annual service is about to renew. This is a separate charge from your usual flexible spending.',options:[{label:'Cancel before renewal · €0',cost:0,why:'Cancelling something you do not need avoids a recurring commitment.'},{label:'Renew after checking you will use it · €72',cost:72,why:'Value depends on use, not just whether the monthly equivalent looks small.'},{label:'Choose the premium annual tier · €132',cost:132,why:'Extra features need to be worth the extra €60 to you.'}]},
{title:'A visit you want to make',text:'You plan a visit. Three affordable travel arrangements are available.',options:[{label:'Book flexible tickets · €150',cost:150,why:'Flexibility has a price. It may matter if plans are uncertain.'},{label:'Take the slower connection · €70',cost:70,why:'A lower fare trades money for time.'},{label:'Reschedule and visit online for now · €0',cost:0,why:'Postponing is one option, though some visits cannot wait. A model cannot decide that for you.'}]},
{title:'Prices creep up',text:'This month’s essential costs are €40 higher. The same basket now costs more.',essentialChange:40,options:[{label:'Keep the usual basket · €0 additional change',cost:0,why:'Your essential bill has already risen by €40. Notice what happens to the buffer.'},{label:'Take a small paid task · earn €40',income:40,why:'An income adjustment offsets this month’s increase, if that work is available.'},{label:'Use a confirmed support voucher · €25 help',income:25,why:'Verified assistance can soften a shock. In real life, check the provider and eligibility.'}]},
{title:'A “guaranteed” opportunity',text:'A fictional influencer promises a guaranteed 20% monthly return. There is no independently verifiable evidence.',options:[{label:'Keep the money; reject the claim · €0',cost:0,why:'A high guaranteed return is a warning sign. The promise is not evidence.'},{label:'Pause and investigate through official sources · €0',cost:0,why:'You can check credentials and claims without transferring money.'},{label:'Send €200 · simulated loss €200',cost:200,why:'In this fictional case, the offer is a scam. Social popularity does not establish legitimacy.'}]},
{title:'An urgent repair',text:'A necessary household repair costs €220. Two legitimate assistance options are available.',options:[{label:'Pay the full repair · €220',cost:220,why:'An emergency reserve can prevent an essential repair turning into debt.'},{label:'Use a verified repair support scheme · €120',cost:120,why:'Here the support reduces the bill. Real schemes have their own eligibility rules.'},{label:'Share the cost under an agreed arrangement · €110',cost:110,why:'The scenario assumes someone has agreed to split the bill. Don’t count on unconfirmed help.'}]},
{title:'The end of the year',text:'There is room to celebrate, but another year of bills is ahead.',options:[{label:'Choose a modest celebration · €40',cost:40,why:'Enjoyment can be part of a budget. The question is how it fits the rest of the plan.'},{label:'Spend more on the occasion · €180',cost:180,why:'Look at what remains afterward, including any unpaid debt.'},{label:'Arrange a free shared activity · €0',cost:0,why:'A low-cost plan preserves the buffer without making the occasion meaningless.'}]}
];let state;function reset(){state={month:0,cash:150,reserve:300,debt:0,logs:[]};draw()}function draw(){const s=state;if(s.month===12){RFL.complete('life');root.innerHTML=`<h2>Your year, in perspective.</h2><div class="life-dashboard">${RFL.stat('Cash',M(s.cash))}${RFL.stat('Emergency reserve',M(s.reserve))}${RFL.stat('Debt',M(s.debt))}${RFL.stat('Net position',M(s.cash+s.reserve-s.debt))}</div><div class="note">You began with €450 across cash and reserves and no debt. You end with ${M(s.cash+s.reserve-s.debt,2)} net. ${s.debt>0?'There is still debt to repay. Inspect which months created it.':'You have no debt in this scenario. Consider how the outcome would change with less income or higher essential costs.'} A simulation cannot capture every constraint a household faces.</div><h3>Look back before you replay</h3><ul><li>Which surprise changed your plan most?</li><li>When did the reserve prevent borrowing?</li><li>What did you give up, and was that acceptable?</li></ul>${RFL.dataTable(s.logs,['Month','Income','Costs','Interest','Cash','Reserve','Debt'],['month','income','costs','interest','cash','reserve','debt'],[null,...Array(6).fill(v=>M(v,2))])}<div class="button-row"><button class="button" id="life-replay">Try another year</button></div>`;$('#life-replay').onclick=reset;return}const event=events[s.month];root.innerHTML=`<div class="life-dashboard">${RFL.stat('Month',`${s.month+1} / 12`)}${RFL.stat('Cash',M(s.cash))}${RFL.stat('Reserve',M(s.reserve))}${RFL.stat('Debt',M(s.debt))}</div><div class="month-track" aria-hidden="true">${events.map((_,i)=>`<span class="${i<s.month?'done':''}"></span>`).join('')}</div><div class="lab-columns"><div class="controls"><h3>Set this month’s plan</h3>${RFL.range('life-flex','Flexible spending',0,450,10,200,'euro')}${RFL.range('life-save','Move cash to reserve',0,400,10,150,'euro')}${RFL.range('life-pay','Target debt repayment',0,400,10,100,'euro')}<p class="small muted">Monthly income: ${M(1500+(event.incomeChange||0))}. Essentials: ${M(1050+(event.essentialChange||0))}. Debt interest: 1% per month, charged before repayment. Reserves earn no interest.</p></div><div><div class="life-event"><span class="eyebrow">Month ${s.month+1} · An everyday decision</span><h2>${event.title}</h2><p>${event.text}</p></div><div class="options">${event.options.map((o,i)=>`<button class="option" data-life="${i}">${o.label}</button>`).join('')}</div><div id="life-feedback" aria-live="polite"></div></div></div><details><summary>How this simulation handles money</summary><p>Income is added; essentials, flexible spending and the chosen event cost are subtracted. A cash shortfall uses the reserve first, then creates debt. The target debt repayment is limited to available cash, followed by the chosen transfer into the reserve. Transfers do not create income. Any unused cash carries forward. Choices and events are fictional and repeat on replay.</p></details>`;RFL.bindRanges(root,()=>{});$$('[data-life]',root).forEach(b=>b.onclick=()=>{const o=event.options[+b.dataset.life],income=1500+(event.incomeChange||0)+(o.income||0),costs=1050+(event.essentialChange||0)+ +$('#life-flex').value+(o.cost||0),interest=s.debt*.01;let reserveUsed=0,newDebt=0;s.debt+=interest;s.cash+=income-costs;if(s.cash<0){reserveUsed=Math.min(s.reserve,-s.cash);s.reserve-=reserveUsed;s.cash+=reserveUsed;if(s.cash<0){newDebt=-s.cash;s.debt+=newDebt;s.cash=0}}const repay=Math.min(s.cash,s.debt,+$('#life-pay').value);s.cash-=repay;s.debt-=repay;const saving=Math.min(s.cash,+$('#life-save').value);s.cash-=saving;s.reserve+=saving;s.logs.push({month:s.month+1,income,costs,interest,cash:s.cash,reserve:s.reserve,debt:s.debt});$$('[data-life]',root).forEach(x=>x.disabled=true);$$('input',root).forEach(x=>x.disabled=true);$('#life-feedback').innerHTML=`<div class="feedback"><h3>This month’s result</h3><p>${o.why}</p><p>Income ${M(income)} · costs ${M(costs)} · debt interest ${M(interest,2)}.</p><p>${reserveUsed?`Used ${M(reserveUsed)} from the reserve. `:''}${newDebt?`Borrowed ${M(newDebt)} to close the gap. `:''}Repaid ${M(repay)} of debt and moved ${M(saving)} into reserves.</p><p><strong>Closing balances:</strong> cash ${M(s.cash)}, reserve ${M(s.reserve)}, debt ${M(s.debt)}.</p></div><div class="button-row"><button class="button" id="life-next">${s.month===11?'Review my year':'Next month'}</button></div>`;$('#life-next').onclick=()=>{s.month++;draw();root.scrollIntoView({block:'start',behavior:'instant'})}})}reset();};
engines.week=root=>{const days=[{title:'Monday: groceries',text:'You have €100 for seven days. Housing and utilities are already paid. Choose a realistic food plan.',options:[['Buy ingredients for several meals',24,2,'Planning several meals can make the food budget more predictable.'],['Buy ready-made meals',38,2,'Convenience costs more in this example; it can still be a valid need.'],['Buy only a snack today',4,0,'Money remains, but the food need is not covered. A low spend is not automatically a good outcome.']]},{title:'Tuesday: getting around',text:'You need to travel today and twice more this week.',options:[['Buy a three-trip pass',9,1,'You have covered the known trips.'],['Buy today’s ticket only',4,0,'Two future trips remain unplanned.'],['Use a safe available cycling route',0,1,'This option works because the scenario gives you a safe route and a working bicycle.']]},{title:'Wednesday: a plan with friends',text:'Your friends suggest meeting up.',options:[['Suggest a free shared activity',0,1,'Social connection does not always need spending.'],['Meet for a modest café visit',8,1,'A small planned expense can fit.'],['Choose an expensive evening',28,1,'Enjoyment matters; check what the remaining days require.']]},{title:'Thursday: unexpected medicine',text:'A necessary prescribed item has a €15 out-of-pocket cost in this fictional case.',options:[['Pay for the necessary item',15,1,'Essential health needs should be accounted for in a workable plan.'],['Use verified assistance available in this scenario',5,1,'Here, confirmed assistance reduces the cost.'],['Skip it to keep more money',0,0,'The balance looks better, but the essential need is unmet. This is not rewarded.']]},{title:'Friday: an online offer',text:'A message promises to double €20 by tomorrow.',options:[['Keep the money and ignore the offer',0,1,'An implausible guaranteed return is a warning sign.'],['Check through independent trusted sources',0,1,'Verification need not involve a transfer.'],['Send €20: it disappears in this scenario',20,0,'The loss is fictional. Popularity or urgency is not evidence.']]},{title:'Saturday: a small repair',text:'An item you need breaks. You have two safe repair options.',options:[['Pay the repair shop',12,1,'A small buffer helps with a necessary unplanned cost.'],['Use an available community repair session',4,1,'This scenario gives you an available lower-cost option.'],['Leave it broken for now',0,0,'The immediate cost disappears, but the need remains unresolved.']]},{title:'Sunday: look ahead',text:'You know a small cost is due next week.',options:[['Keep at least €10 available',0,1,'A little breathing room can make next week easier.'],['Buy an optional treat',7,1,'Consider the balance after the treat.'],['Spend €18 on a nonessential offer',18,0,'A discount does not make a purchase necessary.']]}];let day=0,balance=100,needs=0,log=[];function draw(){if(day===days.length){RFL.complete('week');root.innerHTML=`<h2>Seven days, several trade-offs.</h2><div class="stat-grid">${RFL.stat('Money left',M(balance))}${RFL.stat('Needs / sound choices',needs+' / 8')}${RFL.stat('€10 buffer',balance>=10?'Kept':'Not kept')}</div><p>${needs<8||balance<0?'Some needs or safe choices were left uncovered. A higher cash balance does not make those outcomes better.':'You covered the stated needs and made considered choices in this scenario.'} ${balance<0?'The plan exceeded the available €100. Think about support and essential priorities; do not treat borrowing as invisible money.':''}</p><p>This is a constrained fictional exercise, not a claim that €100 can cover anyone’s weekly needs.</p><div class="table-scroll"><table><thead><tr><th>Day</th><th>Choice</th><th>Cost</th></tr></thead><tbody>${log.map((x,i)=>`<tr><td>${i+1}</td><td>${x[0]}</td><td>${M(x[1])}</td></tr>`).join('')}</tbody></table></div><button class="button" id="week-again">Try another plan</button>`;$('#week-again').onclick=()=>{day=0;balance=100;needs=0;log=[];draw()};return}const d=days[day];root.innerHTML=`<div class="scenario"><div class="game-progress"><span>Day ${day+1} of 7</span><progress value="${day}" max="7" aria-label="Week progress"></progress><strong>${M(balance)} left</strong></div><h2>${d.title}</h2><p class="lead">${d.text}</p><div class="options">${d.options.map((o,i)=>`<button class="option" data-week="${i}">${o[0]} · ${M(o[1])}</button>`).join('')}</div><div id="week-feedback" aria-live="polite"></div></div>`;$$('[data-week]',root).forEach(b=>b.onclick=()=>{const o=[...d.options[+b.dataset.week]];if(day===6&&+b.dataset.week===0&&balance<10){o[2]=0;o[3]='There is less than €10 left. The buffer goal is not met; saying you will keep it cannot create the missing money.'}balance-=o[1];needs+=o[2];log.push(o);$$('[data-week]',root).forEach(x=>x.disabled=true);$('#week-feedback').innerHTML=`<div class="feedback ${o[2]?'good':'retry'}"><p>${o[3]}</p><p>Remaining budget: <strong>${M(balance)}</strong>.</p>${balance<0?'<p>Your plan has exceeded the available funds. The negative amount is an unmet funding gap, not automatically available credit.</p>':''}</div><button class="button" id="week-next" style="margin-top:18px">${day===6?'Review the week':'Next day'}</button>`;$('#week-next').onclick=()=>{day++;draw()}})}draw()};
engines.escape=root=>{const puzzles=[{title:'Lock 1 · The sale label',text:'A €50 bag is discounted by 20%. Enter the final price in euros.',answer:40,hint:'Find 20% of €50, then subtract it.',explanation:'20% × €50 = €10. The final price is €40.'},{title:'Lock 2 · Two years later',text:'€100 earns 10% each year, compounded annually. There are no deposits or fees. Enter the balance after two years.',answer:121,hint:'Apply the second 10% to the balance after year one.',explanation:'€100 × 1.10 × 1.10 = €121. The second year earns interest on €110.'},{title:'Lock 3 · The recurring fee',text:'A service costs €3.50 each month. Enter the cost of twelve months at that price.',answer:42,hint:'There are twelve payments.',explanation:'€3.50 × 12 = €42. A small monthly cost can still matter over a year.'},{title:'Lock 4 · The urgent request',text:'A voice message that sounds like a friend asks you to send money immediately. What opens the safe route?',options:['Send the money because you recognise the voice','Call the friend using a number you already know','Ask the message sender where to send it'],answer:1,hint:'Use a channel that does not depend on the suspicious message.',explanation:'A familiar voice can be imitated. A known independent contact route lets you verify the request.'},{title:'Lock 5 · The confident answer',text:'An AI says: “A 50% fall followed by a 50% rise gets you back to where you started.” Starting from €100, what is the actual final value?',answer:75,hint:'First halve €100. Then increase that new amount by half.',explanation:'€100 → €50 → €75. The percentage bases are different.'}];let i=0;function draw(){if(i===puzzles.length){RFL.complete('escape');root.innerHTML=`<div class="scenario"><span class="eyebrow">All five locks opened</span><h2>You found your way through.</h2><p>You used changing percentage bases, compound interest, recurring costs and independent verification. Those are useful outside a puzzle too.</p><p class="small">Recorded in My learning.</p><button class="button" id="escape-again">Play again</button></div>`;$('#escape-again').onclick=()=>{i=0;draw()};return}const p=puzzles[i];root.innerHTML=`<div class="scenario"><div class="game-progress"><span>Lock ${i+1} of 5</span><progress value="${i}" max="5" aria-label="Escape room progress"></progress></div><h2>${p.title}</h2><p class="lead">${p.text}</p>${p.options?`<div class="options">${p.options.map((x,j)=>`<button class="option" data-lock="${j}">${x}</button>`).join('')}</div>`:'<form id="lock-form"><label for="lock-answer">Your answer (€)</label><input type="number" id="lock-answer" step="0.01" required><button class="button" type="submit" style="margin-left:10px">Unlock</button></form>'}<details><summary>A small hint</summary><p>${p.hint}</p></details><div id="lock-feedback" aria-live="polite"></div></div>`;function answer(n){if(Math.abs(n-p.answer)>1e-8||!Number.isFinite(n)){feedback($('#lock-feedback'),'The lock stays closed','Try again. Use the hint if you want a nudge.',false);return}$$('button,input',root).forEach(x=>x.disabled=true);$('#lock-feedback').innerHTML=`<div class="feedback good"><h3>Unlocked.</h3><p>${p.explanation}</p></div><div class="button-row"><button class="button" id="lock-next">${i===4?'Leave the room':'Next lock'}</button></div>`;$('#lock-next').onclick=()=>{i++;draw()}}if(p.options)$$('[data-lock]',root).forEach(b=>b.onclick=()=>answer(+b.dataset.lock));else $('#lock-form').onsubmit=e=>{e.preventDefault();answer(+$('#lock-answer').value)}}draw()};

engines.crossword=root=>{const words=[{"word": "INFLATION", "clue": "A general rise in prices that reduces the buying power of money.", "r": 6, "c": 2, "d": 0, "n": 6}, {"word": "INTEREST", "clue": "The cost of borrowing money, or an amount earned on eligible savings.", "r": 5, "c": 10, "d": 1, "n": 5}, {"word": "PHISHING", "clue": "A deceptive message that tries to get you to reveal information or take an unsafe action.", "r": 1, "c": 2, "d": 1, "n": 1}, {"word": "PRIVACY", "clue": "Keeping control over access to personal information.", "r": 2, "c": 6, "d": 1, "n": 3}, {"word": "VERIFY", "clue": "Check a claim against a trustworthy independent source.", "r": 2, "c": 4, "d": 1, "n": 2}, {"word": "BUDGET", "clue": "A plan for money coming in and going out.", "r": 10, "c": 6, "d": 0, "n": 7}, {"word": "SAVING", "clue": "Putting money aside for later.", "r": 3, "c": 8, "d": 1, "n": 4}];
const grid={},starts={};let direction=0,hints=0;words.forEach(w=>{starts[w.r+','+w.c]=w.n;for(let i=0;i<w.word.length;i++)grid[(w.r+i*w.d)+','+(w.c+i*(1-w.d))]=w.word[i]});
root.innerHTML=`<div class="lab-columns"><div class="clues"><h3>Connect the ideas</h3><p>Select a clue to start. Type letters, or use arrow keys to move. There is no timer.</p>${[0,1].map(d=>`<h4>${d?'Down':'Across'}</h4><ol>${words.filter(w=>w.d===d).sort((a,b)=>a.n-b.n).map(w=>`<li value="${w.n}"><button class="text-link" data-clue="${w.n}-${d}">${w.clue} (${w.word.length})</button></li>`).join('')}</ol>`).join('')}<div class="button-row"><button class="button" id="cross-check">Check the grid</button><button class="button secondary" id="cross-hint">Reveal one letter</button></div><p class="small" id="cross-hint-count">Hints used: 0</p><div id="cross-feedback" aria-live="polite"></div></div><div><div class="crossword" role="group" aria-label="Resilience crossword">${Array.from({length:169},(_,i)=>{const r=Math.floor(i/13),c=i%13,key=r+','+c;return `<div class="cross-cell"${grid[key]?` data-cell="${key}"`:''}>${grid[key]?`${starts[key]?`<span aria-hidden="true">${starts[key]}</span>`:''}<input type="text" inputmode="text" maxlength="1" autocomplete="off" spellcheck="false" aria-label="Row ${r+1}, column ${c+1}${starts[key]?', clue '+starts[key]:''}" data-position="${key}">`:''}</div>`}).join('')}</div><p class="small muted" style="margin-top:16px">Green cells are correct. Amber cells need another look. Definitions are simplified for this learning activity.</p></div></div>`;
function focus(r,c){const el=$(`[data-position="${r},${c}"]`,root);if(el){el.focus();el.select()}}
$$('[data-clue]',root).forEach(b=>b.onclick=()=>{const [n,d]=b.dataset.clue.split('-').map(Number),w=words.find(w=>w.n===n&&w.d===d);direction=d;focus(w.r,w.c)});
$$('[data-position]',root).forEach(el=>{el.oninput=()=>{el.value=el.value.replace(/[^a-z]/gi,'').toUpperCase();el.parentElement.classList.remove('wrong','right');if(el.value){const [r,c]=el.dataset.position.split(',').map(Number);focus(r+direction,c+1-direction)}};el.onkeydown=e=>{const [r,c]=el.dataset.position.split(',').map(Number),map={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(map[e.key]){e.preventDefault();const [dr,dc]=map[e.key];direction=dr?1:0;focus(r+dr,c+dc)}}});
$('#cross-check').onclick=()=>{let right=0;$$('[data-position]',root).forEach(el=>{const good=el.value.toUpperCase()===grid[el.dataset.position];el.parentElement.classList.toggle('right',good);el.parentElement.classList.toggle('wrong',!good);if(good)right++});const all=right===Object.keys(grid).length;feedback($('#cross-feedback'),all?'The ideas connect.':`${right} of ${Object.keys(grid).length} letters correct`,all?'You completed the seven-word crossword. Try explaining each word with an example of your own. Recorded in My learning.':'Use the highlighted cells and clues to revise the remaining letters.',all);if(all)RFL.complete('crossword')};
$('#cross-hint').onclick=()=>{const el=$$('[data-position]',root).find(x=>x.value!==grid[x.dataset.position]);if(el){el.value=grid[el.dataset.position];el.parentElement.classList.add('right');hints++;$('#cross-hint-count').textContent='Hints used: '+hints;el.focus()}};
};
})();
